  })
  .wip(3);

const contractsUs = H.lane('contracts-us').of(contract)
  .from(contractWebhook('us', 1), manual('legal-ops-us'))
  .store(documents)
  .handle(contractFlow, {
    exits: { returned: { to: drafting, atMost: 1, then: declined }, rejected, executed },
    retry: { retries: 1, exhausted: failed },
